import '@servicenow/sdk/global'
import { Flow, wfa, trigger, action, FlowArray, FlowObject } from '@servicenow/sdk/automation'
import { StringColumn } from '@servicenow/sdk/core'

/**
 * Test flow for nested forEach loops with data pills
 * Tests that data pills correctly reference the appropriate forEach loop UUID
 *
 * This tests the fix for nested forEach where:
 * - Outer loop uses parameter name 'dept'
 * - Inner loop uses parameter name 'category'
 * - Data pills like ${dept.name} should become {{outerUUID.item.name}}
 * - Data pills like ${category.name} should become {{innerUUID.item.name}}
 * - Each forEach only replaces its own parameter's data pills
 */
Flow(
    {
        $id: Now.ID['nested_foreach_test_flow'],
        name: 'Nested ForEach Data Pills Test Flow',
        description: 'Tests nested forEach loops with data pills referencing outer and inner loop items',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        flowVariables: {
            departments: FlowArray({
                label: 'Departments',
                mandatory: true,
                elementType: FlowObject({
                    fields: {
                        name: StringColumn({ label: 'Department Name', mandatory: true }),
                        manager: StringColumn({ label: 'Manager', mandatory: true }),
                    },
                    label: 'Department',
                    mandatory: true,
                }),
                childName: 'department',
            }),
            categories: FlowArray({
                label: 'Categories',
                mandatory: true,
                elementType: FlowObject({
                    fields: {
                        name: StringColumn({ label: 'Category Name', mandatory: true }),
                    },
                    label: 'Category',
                    mandatory: true,
                }),
                childName: 'category',
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['nested_foreach_trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Outer forEach loop - iterating over departments from flow variables
        wfa.flowLogic.forEach(
            wfa.dataPill(params.flowVariables.departments, 'array.object'),
            { $id: Now.ID['foreach_departments'], annotation: 'Iterate through departments' },
            (dept) => {
                // Action 1: Uses only outer loop data pill
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_dept_only'] },
                    {
                        log_level: 'info',
                        log_message: `Department: ${wfa.dataPill(dept.name, 'string')}, Manager: ${wfa.dataPill(dept.manager, 'string')}`,
                    }
                )

                // Inner forEach loop - iterating over categories from flow variables
                wfa.flowLogic.forEach(
                    wfa.dataPill(params.flowVariables.categories, 'array.object'),
                    { $id: Now.ID['foreach_categories'], annotation: 'Iterate through categories' },
                    (category) => {
                        // Action 2: Uses both outer and inner loop data pills
                        wfa.action(
                            action.core.log,
                            { $id: Now.ID['log_dept_and_category'] },
                            {
                                log_level: 'info',
                                log_message: `Dept: ${wfa.dataPill(dept.name, 'string')}, Category: ${wfa.dataPill(category.name, 'string')}, Manager: ${wfa.dataPill(dept.manager, 'string')}`,
                            }
                        )

                        // Action 3: Uses only inner loop data pill
                        wfa.action(
                            action.core.log,
                            { $id: Now.ID['log_category_only'] },
                            {
                                log_level: 'info',
                                log_message: `Category: ${wfa.dataPill(category.name, 'string')}`,
                            }
                        )
                    }
                )

                // Action 4: After inner loop, uses only outer loop data pill again
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_dept_after_inner'] },
                    {
                        log_level: 'info',
                        log_message: `Back to outer loop - Department: ${wfa.dataPill(dept.name, 'string')}`,
                    }
                )
            }
        )
    }
)
